   let result={};try{result=await response.json()}catch(_){}
   if(response.status!==201||!response.ok||!result.storageRef||typeof result.storageRef.provider!=='string'||!result.storageRef.provider||typeof result.storageRef.objectKey!=='string'||!result.storageRef.objectKey.trim()||result.storageRef.objectKey.length>512||/[\u0000-\u001f\u007f]/u.test(result.storageRef.objectKey)||result.mimeType!==match[1]||result.sizeBytes!==bytes.byteLength||String(result.sha256||'').toLowerCase()!==sha256){const error=new Error(result.error?.code||'MEDIA_UPLOAD_INVALID_RESPONSE');error.status=response.status>=500?response.status:response.status===429?429:response.status>=400?response.status:502;error.retryAfterMs=RotaMotoSyncReconciliation.retryAfterMilliseconds(response.headers?.get?.('Retry-After'));throw error}
