function syncOperationKey(type,record){return `operation:${type}:${record.eventId||record.id}`}
function validCompanySettingsSnapshot(value,companyId){return !!value&&value.authority==='restaurant'&&value.companyId===companyId&&Number.isSafeInteger(value.revision)&&value.revision>=0&&typeof value.name==='string'&&(value.supportPhone===null||typeof value.supportPhone==='string')&&(value.timeZone===null||typeof value.timeZone==='string')&&['nearest_extension','nearest_origin_round_robin'].includes(value.routeGroupingPolicy)&&(value.operationalLocation===null||Number.isFinite(value.operationalLocation.latitude)&&value.operationalLocation.latitude>=-90&&value.operationalLocation.latitude<=90&&Number.isFinite(value.operationalLocation.longitude)&&value.operationalLocation.longitude>=-180&&value.operationalLocation.longitude<=180&&value.operationalLocation.provenance==='operator_confirmed')}
