let restaurantPresence=null,restaurantPresenceChecked=false,restaurantPresenceUnavailable=false;
function paintRestaurantPresence(){const state=$('#restaurantPresenceState'),help=$('#restaurantPresenceHelp'),checkIn=$('#restaurantCheckIn'),checkOut=$('#restaurantCheckOut'),qr=$('#restaurantPresenceQr');if(!state||!help||!checkIn||!checkOut)return;const present=restaurantPresence?.present===true,linked=!!syncSession?.driverId;state.textContent=!linked?'Presença não consultada':restaurantPresenceUnavailable?'Presença não confirmada':present?(restaurantPresence.confirmed?'Presença confirmada pelo restaurante':'Chegada registrada · aguardando confirmação'):restaurantPresenceChecked?'Fora da fila do restaurante':'Presença ainda não consultada';help.textContent=!linked?'Conecte-se à conta vinculada ao restaurante para consultar ou confirmar sua chegada. O GPS não confirma presença.':navigator.onLine===false?'Sem conexão. A presença não foi confirmada; tente novamente quando a conexão voltar.':restaurantPresenceUnavailable?'O servidor não respondeu. Sua presença continua sem confirmação. Tente novamente.':present?`${restaurantPresence.position?`Posição ${restaurantPresence.position} na fila. `:''}${restaurantPresence.confirmed?'Presença validada pelo restaurante.':'Chegada registrada; aguarde a confirmação do restaurante.'} O GPS não confirma presença.`:restaurantPresenceChecked?'Você ainda não entrou na fila do restaurante. Para entrar, fique Online e registre sua chegada.':'Aguardando consulta ao restaurante. O GPS não confirma presença.';checkIn.hidden=present;checkIn.disabled=!linked||navigator.onLine===false||driverAvailabilityUnconfirmed||driverAvailability?.effectiveStatus!=='online';checkOut.hidden=!present;checkOut.disabled=!linked||navigator.onLine===false;if(qr)qr.disabled=!linked||navigator.onLine===false||driverAvailabilityUnconfirmed||driverAvailability?.effectiveStatus!=='online'}
async function refreshRestaurantPresence(){if(!syncSession?.driverId){restaurantPresenceChecked=false;restaurantPresenceUnavailable=false;paintRestaurantPresence();return null}if(navigator.onLine===false){restaurantPresenceUnavailable=true;paintRestaurantPresence();return null}try{const result=await availabilityRequest('/restaurant-driver-queue');restaurantPresence=result.presence||null;restaurantPresenceChecked=true;restaurantPresenceUnavailable=false;paintRestaurantPresence();return restaurantPresence}catch(error){restaurantPresence=null;restaurantPresenceUnavailable=true;paintRestaurantPresence();return null}}
async function submitRestaurantCheckIn(qrToken=null){if(!syncSession?.driverId||navigator.onLine===false)throw new Error('Entre na conta do Motoboy vinculada ao restaurante e conecte-se para confirmar a chegada.');if(driverAvailability?.effectiveStatus!=='online')throw new Error('Fique Online antes de registrar sua chegada ao restaurante.');const path=qrToken?'/restaurant-driver-queue/qr-check-in':'/restaurant-driver-queue/check-in';try{const result=await availabilityRequest(path,{method:'POST',body:qrToken?{token:qrToken}:{}});restaurantPresence=result.presence||null;paintRestaurantPresence();toast(restaurantPresence?.confirmed?'Check-in confirmado pelo QR do restaurante.':'Chegada registrada. Aguarde a confirmação do restaurante.');await refreshRestaurantPresence();return result}catch(error){await refreshRestaurantPresence();throw error}}
async function submitRestaurantCheckOut(){if(navigator.onLine===false)throw new Error('Sem conexão. A saída não foi confirmada pelo servidor.');const result=await availabilityRequest('/restaurant-driver-queue/check-out',{method:'POST',body:{}});restaurantPresence=result.presence||null;paintRestaurantPresence();await refreshRestaurantPresence();toast('Saída da fila confirmada pelo Restaurante.')}
