$('#restaurantPresenceQr')?.addEventListener('click',openRestaurantPresenceQrScanner);
async function reconcileAvailabilityAfterReconnect(){if(!syncSession?.driverId)return;await restoreDriverAvailability();if(driverAvailabilityPending){const pending=driverAvailabilityPending;try{await submitAvailabilityCommand(pending.desiredStatus,pending)}catch(error){console.warn('Disponibilidade permanece sem confirmação.',error)}}else await refreshDriverAvailability()}
