async function updateDriverAddress(lat,lng){
  const seq=++driverAddressSeq;driverAddressBusy=true;
  try{const r=await reverseAddress(lat,lng);if(seq!==driverAddressSeq)return;driverAddress=r?.display_name||canonicalAddress(r)||'';driverAddressCoords={lat:+lat,lng:+lng};updateDriverMarkerContent()}catch{}finally{if(seq===driverAddressSeq)driverAddressBusy=false}
}
function gpsAgeLabel(position=lastGps){return RotaMotoGpsQuality.ageText(position?.timestamp)}
function driverPopupHtml(){const when=lastGps?.at?new Date(lastGps.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';return `<b>Posição do aparelho</b><br><span>Horário da leitura: ${when} · ${esc(gpsAgeLabel())}</span><br><span>${esc(gpsAccuracyLabel(lastGps?.accuracy))}</span><br><span>${esc(addressDisplay()||'Endereço não localizado')}</span>`}
function updateDriverMarkerContent(){
  const time=lastGps?.at?new Date(lastGps.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
  const tip=`<b>Localização do aparelho</b> · ${time}<br>${esc(gpsAgeLabel())}<br>${esc(gpsAccuracyLabel(lastGps?.accuracy))}`;
  if(driverMarker){driverMarker.bindPopup(driverPopupHtml());driverMarker.bindTooltip(tip,{permanent:false})}
  if(previewDriverMarker){previewDriverMarker.bindPopup(driverPopupHtml());previewDriverMarker.bindTooltip(tip,{permanent:false})}
  const t=$('#trackingBadge');
  if(t&&lastGps){const fresh=Date.now()-lastGps.timestamp<60000;t.innerHTML=`<span></span><div><b>${fresh?'Localização atualizada':'Última localização conhecida'} · ${time}</b><small>${esc(gpsAccuracyLabel(lastGps.accuracy))} · ${esc(gpsAgeLabel())}</small></div>`;t.classList.toggle('active',fresh);t.classList.toggle('searching',false);t.classList.toggle('stale',!fresh)}
}
async function persistCanonicalLocation(race,position){
 if(locationWriteBusy||!race?.canonicalDelivery||!globalThis.crypto?.randomUUID)return;
 const accuracy=Number(position?.accuracy);if(!Number.isFinite(accuracy)||accuracy>100)return;
 const point={lat:Number(position.latitude),lng:Number(position.longitude)},now=Date.now();if(!Number.isFinite(point.lat)||point.lat< -90||point.lat>90||!Number.isFinite(point.lng)||point.lng< -180||point.lng>180)return;
 if(lastPersistedLocation&&(now-lastPersistedLocation.at<30000&&distance(lastPersistedLocation,point)<0.025))return;
 locationWriteBusy=true;
 try{const recordedAt=new Date(Number(position.timestamp)||now).toISOString(),record={id:crypto.randomUUID(),deliveryId:race.deliveryId,companyId:race.companyId,latitude:point.lat,longitude:point.lng,accuracyM:accuracy,recordedAt,createdAt:recordedAt,updatedAt:recordedAt,version:1,sync:{state:'pending'}};await tx(['locations','outbox'],'readwrite',stores=>{stores.objectStore('locations').put(record);stores.objectStore('outbox').put({id:record.id,type:'LocationPoint',status:'pending',createdAt:now})});lastPersistedLocation={...point,at:now};if(syncBootstrapReady)scheduleServerSync()}catch(error){console.warn('location persistence failed',error);const badge=$('#trackingBadge');if(badge){badge.setAttribute('aria-label','GPS ativo; não foi possível salvar a localização neste aparelho.');badge.classList.add('error')}}finally{locationWriteBusy=false}
}
function setDriverPosition(lat,lng,accuracy=null,timestamp=Date.now()){const fix=RotaMotoGpsQuality.accept(lat,lng,accuracy,timestamp,lastGps?.timestamp);if(!fix)return false;const prevGps=lastGps,point={lat:fix.lat,lng:fix.lng},moved=prevGps?distance(prevGps,point)>=0.01:false;lastGps=fix;if(!lastMovementAt||moved)lastMovementAt=fix.timestamp;const activeLocationRace=activeGpsRace();if(activeLocationRace)persistCanonicalLocation(activeLocationRace,{latitude:point.lat,longitude:point.lng,accuracy:fix.accuracy,timestamp:fix.timestamp}).catch(()=>{});
  const active=activeGpsRace(),accOk=accuracy==null||+accuracy<=100;if(active&&moved&&accOk){commitRiderCommand(next=>{const race=next.races.find(r=>r.id===active.id&&['route','arrived'].includes(r.status));if(!race||!Number.isFinite(num(race.gpsLastPoint?.lat))||!Number.isFinite(num(race.gpsLastPoint?.lng)))return{commit:false};const leg=distance(race.gpsLastPoint,point);if(leg<0.01||leg>2)return{commit:false};race.gpsDistanceKm=num(race.gpsDistanceKm)+leg;race.gpsLastPoint={lat:point.lat,lng:point.lng};return{}},{render:false}).catch(error=>{console.error('GPS distance persistence failed',error);toast('Não foi possível salvar a distância do GPS.','error')})}
  if(map){driverAccuracyCircle=updateGpsAccuracyCircle(map,driverAccuracyCircle,lastGps);if(!driverMarker){driverMarker=L.marker([lat,lng],{icon:L.divIcon({className:'driver-location-marker',html:'<span></span>',iconSize:[24,24],iconAnchor:[12,12]})}).addTo(map);driverMarker.on('click',()=>driverMarker.openPopup())}else driverMarker.setLatLng([lat,lng]);driverMarker.addTo(map)}
  if(homeMap){homeGpsAccuracyCircle=updateGpsAccuracyCircle(homeMap,homeGpsAccuracyCircle,lastGps);updateHomeGpsMarker()}setHomeGpsStatus(`Localização do aparelho (${gpsAccuracyLabel(lastGps.accuracy)}). Isso não confirma presença no restaurante.`)
  if(routePreviewMap&&$('#routesScreen')?.classList.contains('active')){previewDriverAccuracyCircle=updateGpsAccuracyCircle(routePreviewMap,previewDriverAccuracyCircle,lastGps);if(!previewDriverMarker){previewDriverMarker=L.marker([lat,lng],{icon:L.divIcon({className:'driver-location-marker',html:'<span></span>',iconSize:[24,24],iconAnchor:[12,12]})}).addTo(routePreviewMap);previewDriverMarker.on('click',()=>previewDriverMarker.openPopup())}else previewDriverMarker.setLatLng([lat,lng]);previewDriverMarker.addTo(routePreviewMap)}
  updateDriverMarkerContent();if($('#races')?.classList.contains('active'))renderRaces();if($('#home')?.classList.contains('active'))renderHome();if($('#earnings')?.classList.contains('active'))renderEarnings();if(mapScreenActive())renderWorkNext();const prev=driverAddressCoords;const addressMoved=!prev||distance(prev,{lat:+lat,lng:+lng})>=0.05;if(addressMoved||!driverAddress)updateDriverAddress(lat,lng);
  const t=$('#trackingBadge');if(t){t.classList.remove('searching','error');t.classList.add('active');updateDriverMarkerContent()}
}

function mapScreenActive(){return $('#mapScreen')?.classList.contains('active')}
function startTracking(){if(watchId!==null)return;const t=$('#trackingBadge');if(!state.settings.trackingEnabled){if(t){t.innerHTML='<span></span> GPS pausado';t.title='Ative a localização nos Ajustes para acompanhar a rota.'}setHomeGpsStatus('Ative a localização nos Ajustes para mostrar sua posição.');return}if(!navigator.geolocation){if(t){t.innerHTML='<span></span> Localização indisponível';t.title=locationErrorMessage();t.classList.add('error')}setHomeGpsStatus(locationErrorMessage());return}if(t){t.innerHTML='<span></span> Buscando localização…';t.title='A localização é independente do vínculo e da disponibilidade.';t.classList.add('searching');t.classList.remove('active','error')}navigator.geolocation.getCurrentPosition(p=>{setDriverPosition(p.coords.latitude,p.coords.longitude,p.coords.accuracy,p.timestamp);lastRerouteGps=null;if(mapScreenActive())renderRouteMap();else if($('#routesScreen')?.classList.contains('active')){renderRoutePreview(optimizedOrder.length?optimizedOrder:routeRaces());requestRoadDistances(optimizedOrder.length?optimizedOrder:routeRaces())}},error=>{if(t){t.innerHTML='<span></span> Localização indisponível';t.title=locationErrorMessage(error);t.classList.remove('active','searching');t.classList.add('error')}setHomeGpsStatus(locationErrorMessage(error))}, {enableHighAccuracy:true,maximumAge:0,timeout:15000});watchId=navigator.geolocation.watchPosition(p=>{setDriverPosition(p.coords.latitude,p.coords.longitude,p.coords.accuracy,p.timestamp);renderWorkNext();if(gpsMovedEnough())scheduleRouteRecalc()},error=>{if(t){t.innerHTML='<span></span> Localização indisponível';t.title=locationErrorMessage(error);t.classList.remove('active','searching');t.classList.add('error')}setHomeGpsStatus(locationErrorMessage(error))},{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
function stopTracking(){if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null}const t=$('#trackingBadge');if(t){t.innerHTML='<span></span> GPS parado';t.classList.remove('active','searching','error')}}
$('#optimizeBtn').onclick=optimizeRoute;$('#routeOverview').onclick=()=>{closeMapPopups();fitRoutePreviewOverview();toast('Visão geral das entregas.')} ;$('#googleNav').onclick=()=>openNavigationBatch('google');$('#wazeNav').onclick=()=>openNavigationBatch('waze');$('#osmandNav').onclick=()=>openNavigationBatch('osmand');$('#preferredNav').onclick=()=>openNavigationBatch(state.settings.navigationProvider||'osmand');$('#locateMe').onclick=async()=>{try{const p=await getPosition();setDriverPosition(p.coords.latitude,p.coords.longitude,p.coords.accuracy,p.timestamp);map.setView([p.coords.latitude,p.coords.longitude],16);toast('Mapa centralizado na sua localização.')}catch(error){toast(locationErrorMessage(error),'error')}};$('#workOverview').onclick=()=>{closeMapPopups();workOverviewUsed=true;fitWorkMapOverview();toast('Visão geral das entregas.')} ;
function setRouteMapFullscreen(expanded){routeFullscreen=Boolean(expanded);const wrap=$('#mapWrap'),button=$('#fullscreenMap');if(!wrap||!button)return;wrap.classList.toggle('fullscreen',routeFullscreen);button.innerHTML=`<svg><use href="#i-${routeFullscreen?'minimize':'expand'}"/></svg>`;button.setAttribute('aria-label',routeFullscreen?'Sair da tela ampliada':'Ampliar mapa');button.setAttribute('aria-expanded',routeFullscreen?'true':'false');requestAnimationFrame(()=>map?.invalidateSize({pan:false}))}$('#fullscreenMap').onclick=()=>setRouteMapFullscreen(!routeFullscreen);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&routeFullscreen)setRouteMapFullscreen(false)});window.addEventListener('resize',()=>{if(routeFullscreen)requestAnimationFrame(()=>map?.invalidateSize({pan:false}))});

function closeDaySummary(){const rows=todayRows(),f=financialSnapshot(rows),existing=(state.settings.dayClosures||[]).find(x=>x.date===today());const summary={date:today(),closedAt:new Date().toISOString(),trips:rows.length,km:f.km,realKm:f.realKm,routeKm:f.routeKm,fee:f.fee,cost:f.cost,profit:f.profit};modal('Fechar dia',`<p><b>${new Date().toLocaleDateString('pt-BR')}</b></p><p>${rows.length} entregas · ${f.km.toFixed(1).replace('.',',')} km considerados</p><p>Taxas: <b>${brl(f.fee)}</b></p><p>Custo estimado: <b>${brl(f.cost)}</b></p><p>Resultado estimado: <b>${brl(f.profit)}</b></p>${f.mixed?'<p class="muted">O fechamento usa km reais quando disponíveis e km de rota nas entregas sem GPS suficiente.</p>':''}${existing?'<p class="muted">O dia já foi fechado antes. Salvar novamente atualiza o fechamento.</p>':''}`,[{label:'Cancelar'},{label:'Salvar fechamento',primary:true,onClick:async()=>{try{await commitRiderCommand(next=>{next.settings.dayClosures=[...(next.settings.dayClosures||[]).filter(x=>x.date!==summary.date),summary];return{}});toast('Resumo do dia salvo no histórico.')}catch(error){console.error(error);toast('Não foi possível salvar o fechamento do dia.','error')}}}])}
function historyMatches(r){if(historyPeriod==='all')return true;const days=historyPeriod==='today'?0:Number(historyPeriod)-1;const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-days);return new Date(r.completedAt||r.createdAt)>=start}
function periodDates(){let end=new Date();end.setHours(23,59,59,999);let start=new Date(end);if(currentPeriod==='today')start.setHours(0,0,0,0);else if(currentPeriod==='week')start.setDate(start.getDate()-6),start.setHours(0,0,0,0);else if(currentPeriod==='month')start.setDate(1),start.setHours(0,0,0,0);else if(customStart&&customEnd){start=new Date(customStart+'T00:00:00');end=new Date(customEnd+'T23:59:59.999')}return{start,end}}
function completedInPeriod(){const {start,end}=periodDates();return state.races.filter(r=>r.status==='done'&&r.completedAt&&new Date(r.completedAt)>=start&&new Date(r.completedAt)<=end)}
function renderBarChart(id,data,formatter){const box=$(id);if(!box)return;const max=Math.max(1,...data.map(x=>num(x.value)));box.innerHTML=data.map((x,i)=>{const value=num(x.value),pct=value>0?Math.max(3,value/max*100):0,title=`${x.fullLabel||x.label}: ${formatter(x.value)}${x.count!=null?` · ${x.count} entrega(s)`:''}`;return `<button type="button" class="barCol" data-chart-index="${i}" title="${esc(title)}" aria-label="${esc(title)}"><span class="barVal">${formatter(x.value)}</span><div class="barTrack"><div class="bar${value===0?' is-zero':''}" style="height:${pct}%"></div></div><span class="barLabel">${esc(x.label)}</span></button>`}).join('');box.querySelectorAll('[data-chart-index]').forEach(btn=>btn.onclick=()=>{const x=data[Number(btn.dataset.chartIndex)];if(!x?.fullLabel)return;const f=x.financial||{};modal(x.fullLabel,`<div class="detailGrid"><div><small>Taxas</small><b>${brl(f.fee??x.value)}</b></div><div><small>Entregas</small><b>${x.count??0}</b></div><div><small>Km considerados</small><b>${num(f.km).toFixed(1).replace('.',',')} km</b></div><div><small>Custo estimado</small><b>${brl(f.cost)}</b></div><div><small>Resultado</small><b>${brl(f.profit)}</b></div></div>`,[])})}
function formatDateRangeLabel(start,end){const a=start.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}),b=end.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'});return a===b?a:`${a}–${b}`}

function canonicalEarningsBetween(start,end){return state.earnings.filter(row=>row&&row.canonicalId&&Number.isSafeInteger(row.amountMinor)&&/^[A-Z]{3}$/.test(row.currency||'')&&!row.deletedAt&&Number.isFinite(Date.parse(row.createdAt))&&new Date(row.createdAt)>=start&&new Date(row.createdAt)<=end)}
