async function createMotoBackup(){const stores=RotaMotoStorageSchema.stores,snapshot=await new Promise((resolve,reject)=>{const transaction=(async()=>{const connection=await openDB();return connection.transaction(stores,'readonly')})();transaction.then(txn=>{const rows={};for(const name of stores){const request=txn.objectStore(name).getAll();request.onsuccess=()=>{rows[name]=request.result||[]};request.onerror=()=>reject(request.error)}txn.oncomplete=()=>resolve(rows);txn.onerror=()=>reject(txn.error||new Error('Falha ao ler o banco local para backup.'))}).catch(reject)});return RotaMotoBackupFormat.create({app:'motoboy',schemaVersion:DB_VERSION,stores:snapshot})}
