let responsiveMapResizeTimer=0;const observedMapSizes=new WeakMap();const responsiveMapObserver=typeof ResizeObserver==='function'?new ResizeObserver(entries=>{for(const entry of entries){const {width,height}=entry.contentRect;if(width<=0||height<=0)continue;const previous=observedMapSizes.get(entry.target);if(previous&&Math.abs(previous.width-width)<.5&&Math.abs(previous.height-height)<.5)continue;observedMapSizes.set(entry.target,{width,height});const instance=[homeMap,routePreviewMap,map,formMap].find(candidate=>candidate?.getContainer?.()===entry.target);if(instance)requestAnimationFrame(()=>{if(entry.target.isConnected&&entry.target.clientWidth>0)instance.invalidateSize({pan:false})})}}):null;function invalidateVisibleMaps(){clearTimeout(responsiveMapResizeTimer);responsiveMapResizeTimer=setTimeout(()=>{for(const instance of [homeMap,routePreviewMap,map,formMap]){const container=instance?.getContainer?.();if(container?.isConnected&&container.clientWidth>0){responsiveMapObserver?.observe(container);instance.invalidateSize({pan:false})}}},180)}window.addEventListener('resize',invalidateVisibleMaps);window.addEventListener('orientationchange',invalidateVisibleMaps);window.visualViewport?.addEventListener('resize',invalidateVisibleMaps);document.addEventListener('visibilitychange',()=>{if(!document.hidden)invalidateVisibleMaps()});
